out=['## Comparison with every substantive supplied context entry','', 'All statuses below are those actually supplied, with their stated limitations. Each comparison has its own recorded search against both context files. The backing research returns and earlier package files were not supplied independently; an ellipsis in the register remains a limit on the comparison.','', '| Entry and supplied status | Supplied source and location | Relation to these pages | Notes |','|---|---|---|---|']
searches=[]
for id,status,source,where,relation,notes,q in rows:
 r=subprocess.run(['rg','-ni','--',q,'context/README.md','context/notes/RESULTS_STATE.md'],cwd=root.parent,capture_output=True,text=True)
 assert r.returncode in(0,1),(id,r.stderr)
 hits=[]
 for line in r.stdout.splitlines():
  p,n,s=line.split(':',2); m=re.search(r'^- \*\*(.+?)\*\*',s)
  hits.append({'file':p.removeprefix('context/'),'line':int(n),'entry':m.group(1)if m else 'context prose'})
